+        for (int nodeNum = 1; nodeNum <= numNodes; ++nodeNum) {
+            int zone = nodeNum % numZones;
+            DiscoveryNodeRole role = (zone < numMlZones) ? randomFrom(MASTER_ROLE, DATA_ROLE, ML_ROLE) : randomFrom(MASTER_ROLE, DATA_ROLE);
