+                        assignmentPlan.assignModelToNode(m, n, allocations);
+                        weights.put(Tuple.tuple(m, n), w);
+                        w -= dw;
+                        break;
+                    }
+                }
+            } while (lastW != w && assignmentPlan.getRemainingAllocations(m) > 0);
+        }
